public class Main {
    static final class Ordem {
        private final long id;
        private boolean concluida;
        Ordem(long id) {
            if (id <= 0) throw new IllegalArgumentException("ID invalido");
            this.id = id;
        }
        void concluir() {
            if (concluida) throw new IllegalStateException("Ja concluida");
            concluida = true;
        }
        String resumo() { return id + ":" + concluida; }
    }
    public static void main(String[] args) {
        Ordem ordem = new Ordem(42);
        ordem.concluir();
        System.out.println(ordem.resumo());
    }
}

import java.util.List;
public class Main {
    enum Status { ABERTA, CONCLUIDA }
    record Resumo(long id, Status status, List<String> itens) {
        Resumo {
            if (id <= 0 || status == null) throw new IllegalArgumentException();
            itens = List.copyOf(itens);
        }
    }
