        Resumo r = new Resumo(7, Status.ABERTA, List.of("camera"));
        System.out.println(r.id() + ":" + r.status() + ":" + r.itens().size());
    }
}

public class Main {
    interface Notificador { void enviar(String texto); }
    static class Terminal implements Notificador {
        public void enviar(String texto) { System.out.println(texto); }
    }
    static class Confirmar {
        private final Notificador notificador;
        Confirmar(Notificador notificador) { this.notificador = notificador; }
        void executar(long id) { notificador.enviar("Ordem " + id + " confirmada"); }
    }
    public static void main(String[] args) {
        new Confirmar(new Terminal()).executar(8);
    }
}

