import java.util.*;
import java.util.stream.Collectors;
public class Main {
    record Servico(String tecnico, long centavos, boolean concluido) {}
    public static void main(String[] args) {
        List<Servico> servicos = List.of(new Servico("Ana", 1500, true),
            new Servico("Ana", 500, true), new Servico("Beto", 900, false));
        long total = servicos.stream().filter(Servico::concluido)
            .mapToLong(Servico::centavos).sum();
        Map<String, Long> porTecnico = servicos.stream().filter(Servico::concluido)
            .collect(Collectors.groupingBy(Servico::tecnico, Collectors.summingLong(Servico::centavos)));
        System.out.println(total);
        System.out.println(porTecnico.get("Ana"));
    }
}

