import com.sun.net.httpserver.HttpServer;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
public class Main {
    public static void main(String[] args) throws Exception {
        HttpServer servidor = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        servidor.createContext("/status", e -> {
            byte[] corpo = "pronto".getBytes(StandardCharsets.UTF_8);
            e.sendResponseHeaders(200, corpo.length);
            try (var saida = e.getResponseBody()) { saida.write(corpo); }
        });
        servidor.start();
        try (HttpClient cliente = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build()) {
            URI uri = URI.create("http://127.0.0.1:" + servidor.getAddress().getPort() + "/status");
            HttpRequest req = HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(3)).GET().build();
            HttpResponse<String> resposta = cliente.send(req, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
            System.out.println(resposta.statusCode());
            System.out.println(resposta.body());
        } finally { servidor.stop(0); }
    }
}

