public class Main {
    interface Estoque { boolean consumir(long equipamento); }
    static final class Memoria implements Estoque {
        private int saldo = 1;
        public synchronized boolean consumir(long equipamento) {
            if (equipamento != 7 || saldo == 0) return false;
            saldo--; return true;
        }
    }
    static final class Confirmar {
        private final Estoque estoque;
        Confirmar(Estoque estoque) { this.estoque = estoque; }
        boolean executar(long equipamento) { return estoque.consumir(equipamento); }
    }
    public static void main(String[] args) {
        Confirmar caso = new Confirmar(new Memoria());
        System.out.println(caso.executar(7));
        System.out.println(caso.executar(7));
    }
}

import com.sun.net.httpserver.HttpServer;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
public class Main {
    public static void main(String[] args) throws Exception {
        HttpServer api = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        api.createContext("/ordens/42", e -> {
            boolean rota = e.getRequestURI().getPath().equals("/ordens/42");
            int status = !rota ? 404 : e.getRequestMethod().equals("GET") ? 200 : 405;
            String texto = status == 200 ? "{\"id\":42,\"status\":\"ABERTA\"}" : "{\"erro\":\"requisicao nao atendida\"}";
            byte[] corpo = texto.getBytes(StandardCharsets.UTF_8);
            e.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
            if (status == 405) e.getResponseHeaders().set("Allow", "GET");
            e.sendResponseHeaders(status, corpo.length);
            try (var saida = e.getResponseBody()) { saida.write(corpo); }
        });
        api.start();
        try (HttpClient cliente = HttpClient.newHttpClient()) {
            URI uri = URI.create("http://127.0.0.1:" + api.getAddress().getPort() + "/ordens/42");
            var req = HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(3)).GET().build();
            var resposta = cliente.send(req, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
            System.out.println(resposta.statusCode());
            System.out.println(resposta.body());
        } finally { api.stop(0); }
    }
}

import java.util.HashMap;
import java.util.Map;
public class Main {
    record Resultado(long ordem, String status) {}
    static final class Confirmador {
        private final Map<String, Resultado> resultados = new HashMap<>();
        private int estoque = 1;
        synchronized Resultado confirmar(String chave, long ordem) {
            Resultado anterior = resultados.get(chave);
            if (anterior != null) {
                if (anterior.ordem() != ordem) throw new IllegalArgumentException("Chave em conflito");
                return anterior;
            }
            if (estoque == 0) throw new IllegalStateException("Sem estoque");
            estoque--;
            Resultado novo = new Resultado(ordem, "CONFIRMADA");
            resultados.put(chave, novo);
            return novo;
        }
        synchronized int saldo() { return estoque; }
    }
    public static void main(String[] args) {
        Confirmador c = new Confirmador();
        System.out.println(c.confirmar("req-1", 42).status());
        System.out.println(c.confirmar("req-1", 42).status());
        System.out.println(c.saldo());
    }
}
